svg.script:
(function(){
  function boot(){
    var svg = document.documentElement;
    if (!svg) return;
    var chk = document.getElementById("fs-show-faces");
    if (chk) chk.addEventListener("change", function(){
      if (chk.checked) svg.classList.remove("hide-faces");
      else svg.classList.add("hide-faces");
    });
    var rs = document.querySelectorAll('input[name="fs-lbl"]');
    for (var k = 0; k < rs.length; k++) {
      rs[k].addEventListener("change", function(ev){
        if (!ev.target.checked) return;
        if (ev.target.value === "name") svg.classList.add("show-names");
        else svg.classList.remove("show-names");
      });
    }
  }
  setTimeout(boot, 0);
})();
